#include "global_correspondence_v2_arithmetic.hpp"
#include "closed_fibers_arithmetic.hpp"
CFPoly hc_read(const Json& j){std::vector<Z> c;for(auto& v:j.arr)c.emplace_back(mpz_class(v.scalar));return CFPoly(c);}
GCField hc_field(const Json& j){return GCField(hc_read(j.at("a")),hc_read(j.at("b")),hc_read(j.at("c")));}
std::string hc_hash(const GCField& f){std::ostringstream out;gc_emit(out,f);auto text=out.str();std::array<unsigned char,32> digest{};SHA256(reinterpret_cast<const unsigned char*>(text.data()),text.size(),digest.data());const char* hex="0123456789abcdef";std::string s;for(auto c:digest){s+=hex[c>>4];s+=hex[c&15];}return s;}
struct HCHeight {CFPoly denominator,a,b,base;int degree=0,checks=0;std::vector<std::string> hashes;};
HCHeight hc_height(std::vector<GCField> functions){
    functions.insert(functions.begin(),GCField(1));HCHeight receipt;CFPoly C{Z(1)};
    for(auto& f:functions){require(f.a.degree()<=f.c.degree()&&(f.b.degree()<0||2*f.b.degree()+7<2*f.c.degree()),"height functions regular at source infinity");C=(C.exact(gc_gcd(C,f.c))*f.c).monic();receipt.hashes.push_back(hc_hash(f));}
    std::vector<CFPoly> aa,bb;CFPoly A,B;for(size_t i=0;i<functions.size();++i){auto q=C.exact(functions[i].c);aa.push_back(functions[i].a*q);bb.push_back(functions[i].b*q);A=A+aa.back().scale(Z(long(i+1)));B=B+bb.back().scale(Z(long(i+1)));}
    auto g=gc_gcd(A,B);require(g.degree()>=0&&gc_gcd(g,C).degree()==0,"fixed height anchor content coprime denominator");auto a=A.exact(g),b=B.exact(g);require(gc_gcd(a,b).degree()==0,"height anchor primitive");CFPoly base=C;
    for(size_t i=0;i<functions.size();++i){base=gc_gcd(base,a*bb[i]-b*aa[i]);base=gc_gcd(base,a*aa[i]-GCField::h*b*bb[i]);}
    for(size_t i=0;i<functions.size();++i){require(((a*bb[i]-b*aa[i])%base).degree()<0&&((a*aa[i]-GCField::h*b*bb[i])%base).degree()<0,"common base ideal exact divisibility");receipt.checks+=2;}
    require((C%base).degree()<0,"base ideal divides denominator");receipt.denominator=C;receipt.a=a;receipt.b=b;receipt.base=base;receipt.degree=2*C.degree()-base.degree();return receipt;
}
void hc_no_affine_singular(const CFPoly& support,const EBPoly& f,const EBPoly& fx,const EBPoly& fy,int& charts,int depth=0){require(depth<=12,"smoothness splitting depth");CFResidue::support=support;
    try{auto d=std::get<0>(xgcd(cf_residue_y(f),cf_residue_y(fx)));auto all=std::get<0>(xgcd(d,cf_residue_y(fy)));require(all.degree()==0,"no affine singular point in exact residue chart");++charts;}
    catch(const CFSplit& s){auto p=s.factor.monic(),q=support.exact(p).monic();require(p.degree()>0&&q.degree()>0,"proper smoothness support split");hc_no_affine_singular(p,f,fx,fy,charts,depth+1);hc_no_affine_singular(q,f,fx,fy,charts,depth+1);}
}
struct HCSmooth {int resultant_degree1=0,resultant_degree2=0,common_degree=0,residue_charts=0;};
HCSmooth hc_smooth(const EBPoly& f){require(f.terms.count({0,4})&&f.terms.at({0,4})!=Z(0),"all infinity points in X=1 chart; degree4 x projection");auto fx=f.partial(0),fy=f.partial(1);auto r=cf_resultant(f,fy),s=cf_resultant(fx,fy);require(r.degree()>=0&&s.degree()>=0,"nonzero affine Jacobian resultants");auto common=gc_gcd(r,s);HCSmooth receipt{r.degree(),s.degree(),common.degree(),0};if(common.degree()>0){auto reduced=common.exact(gc_gcd(common,gc_derivative(common))).monic();hc_no_affine_singular(reduced,f,fx,fy,receipt.residue_charts);}CFPoly f4,f3;for(auto& [e,c]:f.terms){std::vector<Z> t(size_t(e[1]+1),Z(0));t[e[1]]=c;if(e[0]+e[1]==4)f4=f4+CFPoly(t);else if(e[0]+e[1]==3)f3=f3+CFPoly(t);}require(gc_gcd(gc_gcd(f4,gc_derivative(f4)),f3).degree()==0,"projective infinity Jacobian has no zero");require(gc_gcd(GCField::h,gc_derivative(GCField::h)).degree()==0,"source odd curve squarefree");return receipt;}
GCField hc_det(const std::array<std::array<GCField,3>,3>& m){return m[0][0]*(m[1][1]*m[2][2]-m[1][2]*m[2][1])-m[0][1]*(m[1][0]*m[2][2]-m[1][2]*m[2][0])+m[0][2]*(m[1][0]*m[2][1]-m[1][1]*m[2][0]);}
void hc_emit(const HCHeight& h){std::cout<<"{\"polar_degree\":"<<h.degree<<",\"exact_divisibility_checks\":"<<h.checks<<",\"common_denominator\":";gc_emit_poly(std::cout,h.denominator);std::cout<<",\"primitive_anchor_a\":";gc_emit_poly(std::cout,h.a);std::cout<<",\"primitive_anchor_b\":";gc_emit_poly(std::cout,h.b);std::cout<<",\"base_ideal_determinant\":";gc_emit_poly(std::cout,h.base);std::cout<<",\"coordinate_hashes\":[";for(size_t i=0;i<h.hashes.size();++i)std::cout<<(i?",":"")<<'"'<<h.hashes[i]<<'"';std::cout<<"]}";}
int main(int argc,char** argv){try{
    require(argc==6,"usage: degree_polarization kernel3-study global.json formal.json actual-kernel.json generic-bridge.json");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));GCField::h=rational(curve);auto global=read_json(argv[2]),formal=read_json(argv[3]),kernel=read_json(argv[4]),bridge=read_json(argv[5]),model=read_json(root+"/evidence/p192-d7-kernel3-plane-quartic.json");require(kernel.at("recorded_cardinality").integer()==27&&kernel.at("principal_nonzero_member_checks").integer()==26&&kernel.at("outside_nonzero_rank").integer()==10,"completed actual kernel-containment input");EBPoly f;for(auto& t:model.at("terms").arr){auto& e=t.at("exponents");require(e.arr[0].integer()+e.arr[1].integer()+e.arr[2].integer()==4,"homogeneous quartic model");f.add({e.arr[0].integer(),e.arr[1].integer()},Z(mpz_class(t.at("coefficient").scalar)));}auto smooth=hc_smooth(f);std::cerr<<"exact source/quartic affine/infinity smoothness checks pass\n";
    Z a(bridge.at("source_point_X").integer()),y=hc_read(bridge.at("images").arr[2].at("source_V")).at(0);require(y*y==GCField::h.eval(a)&&y!=Z(0)&&GCField::h.eval(a+Z(1))!=y*y,"fixed conjugate-branch pole control point");CFPoly xa{-a,Z(1)},xb{-a-Z(1),Z(1)};GCField control1(CFPoly{Z(1)},{},xa),control2(CFPoly{y},CFPoly{Z(1)},xa*xb*xb*xb);auto c1=hc_height({control1}),c2=hc_height({control2});require(c1.degree==2&&c2.degree==7,"pole controls include branch cancellation and repeated denominator");
    std::vector<GCField> uc,vc;for(auto& c:global.at("U").arr)uc.push_back(hc_field(c));for(auto& c:global.at("V").arr)vc.push_back(hc_field(c));GCResidue::u=GCP(uc);require(GCResidue::u.degree()==3&&GCResidue::u.at(3)==GCField(1),"fixed monic global target cubic");auto xheight=hc_height({-uc[2],uc[1],-uc[0]});require(xheight.degree==36,"fixed elementary-x polar degree36");std::cerr<<"elementary-x common polar degree="<<xheight.degree<<'\n';GCResidue T(GCP{GCField(0),GCField(1)}),V{GCP(vc)};std::vector<GCResidue> sections;for(int i=0;i<=3;++i)for(int j=0;i+j<=3;++j){GCResidue s(1);for(int k=0;k<i;++k)s=s*T;for(int k=0;k<j;++k)s=s*V;sections.push_back(s);}require(sections.size()==10,"ten cubic evaluation columns");std::vector<GCField> plucker;for(int i=0;i<10;++i)for(int j=i+1;j<10;++j)for(int k=j+1;k<10;++k){std::array<std::array<GCField,3>,3> m{};for(int row=0;row<3;++row){m[row][0]=sections[i].p.at(row);m[row][1]=sections[j].p.at(row);m[row][2]=sections[k].p.at(row);}plucker.push_back(hc_det(m));if(plucker.size()%20==0)std::cerr<<"constructed exact Pluecker coordinate "<<plucker.size()<<'\n';}require(plucker.size()==120&&std::find(plucker.begin(),plucker.end(),GCField(1))!=plucker.end(),"all120 minors include unit frame");auto pheight=hc_height(plucker);require(pheight.degree==72,"fixed cubic Pluecker height72");int correspondence_degree=xheight.degree/4,theta_degree=pheight.degree-7*correspondence_degree;require(xheight.degree%4==0&&correspondence_degree==9&&theta_degree==9,"geometric projection/theta degree predictions");
    std::array<std::array<Z,3>,3> D{};for(int i=0;i<3;++i)for(int j=0;j<3;++j)D[i][j]=Z(mpz_class(formal.at("differential").arr[i].arr[j].scalar));Z determinant=D[0][0]*(D[1][1]*D[2][2]-D[1][2]*D[2][1])-D[0][1]*(D[1][0]*D[2][2]-D[1][2]*D[2][0])+D[0][2]*(D[1][0]*D[2][1]-D[1][1]*D[2][0]);require(determinant!=Z(0),"global isogeny differential nonsingular");std::cout<<"{\"scope\":\"P192-kernel3-geometric-degree-and-polarization\",\"standing\":\"producer-unverified\",\"smooth_source\":true,\"smooth_projective_quartic\":true,\"affine_Jacobian_resultant_degrees\":["<<smooth.resultant_degree1<<','<<smooth.resultant_degree2<<"],\"affine_common_support_degree\":"<<smooth.common_degree<<",\"smoothness_residue_charts\":"<<smooth.residue_charts<<",\"pole_control_degrees\":[2,7],\"correspondence_projection_degree\":"<<correspondence_degree<<",\"cubic_Pluecker_degree\":"<<pheight.degree<<",\"theta_pullback_degree\":"<<theta_degree<<",\"nonsingular_differential_determinant\":\""<<determinant.x<<"\",\"recorded_kernel_order\":27,\"isogeny_degree_under_documented_geometric_bridge\":27,\"polarization_multiplier_under_documented_bridge\":3,\"compiled_geometric_proof\":false,\"dual_executed\":false,\"elementary_x_height\":";hc_emit(xheight);std::cout<<",\"cubic_evaluation_height\":";hc_emit(pheight);std::cout<<"}\n";
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
